// Extract payment payload and normalize schema
const body = $input.first().json.body || $input.first().json;
return [{
  json: {
    invoice_id: body.id || body.invoice_id,
    invoice_number: body.invoice_number,
    user_id: body.user_id,
    student_id: body.student_id,
    payer_name: body.parent_name || body.payer_name,
    payer_mobile: body.mobile || body.payer_mobile,
    payer_email: body.email,
    net_amount: parseFloat(body.net_amount || body.amount || 0),
    payment_status: body.payment_status || 'Paid',
    paid_at: body.paid_at || new Date().toISOString(),
    is_renewal: body.is_renewal || 'Yes'
  }
}];

// Generate 24 live class schedule bookings
const student = $node["Lookup Student & Batch Master"].json;
const inv = $node["Normalize Webhook Payload"].json;
const daysMap = { 'Mon': 1, 'Tue': 2, 'Wed': 3, 'Thu': 4, 'Fri': 5, 'Sat': 6, 'Sun': 0 };
const targetDays = student.batch_days.split(',').map(d => daysMap[d.trim()]);

const rows = [];
let curr = new Date('2026-11-04T00:00:00Z');
while (rows.length < 24) {
  curr.setDate(curr.getDate() + 1);
  if (targetDays.includes(curr.getDay())) {
    rows.push({
      bookingrequest_id: 'AUTO_' + inv.invoice_id,
      invoice_id: inv.invoice_id,
      classbatch_id: student.current_classbatch_id,
      class_id: student.class_id,
      user_id: inv.user_id,
      student_id: inv.student_id,
      educator_id: student.educator_id,
      class_date: curr.toISOString().split('T')[0],
      start_time: student.batch_start_time,
      end_time: '17:50:00',
      booking_type: 'Auto_Approved_Zero_Touch',
      is_cancelled: 'No',
      attended_class: 'No'
    });
  }
}
return rows.map(r => ({ json: r }));

